known=json.loads((base/'regression128.json').read_text(encoding='utf-8'))
assert len(rows)==32 and not ({c['answer'] for c in rows}&{c['answer'] for c in known})
for c in rows:
 assert len(c['evidence_anchors'])==3
 for bit,anchors in zip(c['expected'],c['evidence_anchors']):
  assert bool(anchors)==bit and all(a in c['answer'] for a in anchors),c['id']
p=base/'holdout32.json';assert not p.exists();p.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(base/'holdout-freeze.json').write_text(json.dumps(dict(frozen_utc=datetime.now(timezone.utc).isoformat(),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),cases=32,new_vs_known128=True,protocol='No inference until candidate selected and frozen. First pass remains primary. Author labels, same four tasks; no teacher acceptance.'),indent=2),encoding='utf-8')
print('Frozen32 before candidate development')
